using System.Text.Json;
using System.Text.Json.Nodes;
using Trax.Effect.Configuration.Deploy;

namespace Trax.Cli.Deploy.Aws;

/// <summary>
/// The CloudFormation template of one environment: its network, load balancer, database, ECS services, the task
/// that migrates, and the sign-in. Generated from <c>trax.deploy.json</c> and what each host reports, so the stack
/// follows the code. Nothing secret is in it: the database password is generated by Secrets Manager and every
/// secret reaches a task by reference.
/// </summary>
internal static class AwsStack
{
    /// <summary>The parameter that is "1" once the services run, and "0" while a new stack waits for its migration.</summary>
    public const string ScaleParameter = "Scale";

    public const string MigrateImageParameter = "MigrateImage";

    /// <summary>Production only: "true" keeps the database from being deleted, until destroy turns it off.</summary>
    public const string ProtectParameter = "Protect";

    public const string MigrateContainer = "migrate";

    /// <summary>The address range of a VPC the stack creates; also the networks hosts trust forwarded headers from.</summary>
    public const string VpcCidr = "10.0.0.0/16";

    public const int ContainerPort = 8080;

    public const string DatabaseUser = "trax";

    // AWS managed policies and CloudFront managed policies, by their fixed ids.
    private const string TaskExecutionPolicy =
        "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy";
    private const string CachingDisabledPolicy = "4135ea2d-6df8-44a3-9df3-4b5a84be39ad";
    private const string AllViewerOriginRequestPolicy = "216adef6-5c7f-47e4-b989-5492eafa07d3";

    /// <summary>The template parameter carrying <paramref name="service"/>'s image.</summary>
    public static string ImageParameter(string service) => $"{LogicalId(service)}Image";

    /// <summary>The ECS service of <paramref name="service"/>, as the stack's output names it.</summary>
    public static string ServiceOutput(string service) => $"{LogicalId(service)}ServiceName";

    /// <summary>
    /// Builds the template. <paramref name="cloudFrontPrefixList"/> is the region's CloudFront origin-facing prefix
    /// list, which the try profile's load balancer admits; it is not read for production.
    /// </summary>
    public static JsonObject Build(
        DeployFile file,
        string environmentName,
        IReadOnlyDictionary<string, DeployManifest> exports,
        string? cloudFrontPrefixList
    )
    {
        var env = file.Environment(environmentName);
        Check(file, env, exports);
        var stack = file.StackName(environmentName);
        var production = env.Profile == DeployEnvironment.Production;
        var api = file.Services.Keys.FirstOrDefault(s => exports[s].Roles.Contains("api"));
        if (!production && api is not null && cloudFrontPrefixList is null)
            throw new InvalidOperationException(
                "The try profile admits only CloudFront to its load balancer, and the region's CloudFront prefix "
                    + "list was not found."
            );

        var resources = new JsonObject();
        var outputs = new JsonObject();
        var parameters = new JsonObject
        {
            [ScaleParameter] = new JsonObject
            {
                ["Type"] = "String",
                ["AllowedValues"] = new JsonArray("0", "1"),
                ["Default"] = "1",
                ["Description"] =
                    "0 while a new stack waits for its first migration, so no service starts on an empty database.",
            },
            [MigrateImageParameter] = new JsonObject
            {
                ["Type"] = "String",
                ["Description"] =
                    "The image the migrate task runs: the new version of the API service.",
            },
        };
        if (production && env.DatabaseSecretArn is null)
            parameters[ProtectParameter] = new JsonObject
            {
                ["Type"] = "String",
                ["AllowedValues"] = new JsonArray("true", "false"),
                ["Default"] = "true",
                ["Description"] =
                    "Whether the database refuses to be deleted. trax deploy destroy sets it to false first.",
            };
        foreach (var service in file.Services.Keys)
            parameters[ImageParameter(service)] = new JsonObject
            {
                ["Type"] = "String",
                ["Description"] = $"The image the {service} service runs.",
            };

        // ---- Network -------------------------------------------------------------------------------------
        JsonNode vpc;
        JsonNode cidr;
        JsonArray publicSubnets;
        JsonArray serviceSubnets;
        if (env.Network is { } network)
        {
            vpc = network.VpcId;
            cidr = network.Cidr;
            publicSubnets = [.. network.PublicSubnets.Select(s => (JsonNode)s)];
            serviceSubnets = [.. network.PrivateSubnets.Select(s => (JsonNode)s)];
        }
        else
        {
            AddVpc(resources, stack, production);
            vpc = Ref("Vpc");
            cidr = VpcCidr;
            publicSubnets = [Ref("PublicSubnetA"), Ref("PublicSubnetB")];
            serviceSubnets = production
                ? [Ref("PrivateSubnetA"), Ref("PrivateSubnetB")]
                : [Ref("PublicSubnetA"), Ref("PublicSubnetB")];
        }
        // A service in a public subnet reaches ECR, Secrets Manager and the logs through its own public address;
        // its security group admits nothing from outside the load balancer.
        var assignPublicIp = production || env.Network is not null ? "DISABLED" : "ENABLED";

        // ---- Security groups: the default allow-all egress is replaced on every one ----------------------
        resources["TaskSecurityGroup"] = SecurityGroup(
            stack,
            vpc,
            "The Trax services",
            [
                Rule(
                    "tcp",
                    443,
                    443,
                    cidr: "0.0.0.0/0",
                    description: "AWS APIs and the app's own outbound HTTPS"
                ),
            ]
        );
        if (env.DatabaseSecretArn is null)
        {
            resources["DatabaseSecurityGroup"] = SecurityGroup(
                stack,
                vpc,
                "The Postgres database",
                [Rule("-1", null, null, cidr: "127.0.0.1/32", description: "No egress")]
            );
            resources["TaskToDatabase"] = Resource(
                "AWS::EC2::SecurityGroupEgress",
                new JsonObject
                {
                    ["GroupId"] = Ref("TaskSecurityGroup"),
                    ["IpProtocol"] = "tcp",
                    ["FromPort"] = 5432,
                    ["ToPort"] = 5432,
                    ["DestinationSecurityGroupId"] = Ref("DatabaseSecurityGroup"),
                    ["Description"] = "Postgres",
                }
            );
            resources["DatabaseFromTasks"] = Resource(
                "AWS::EC2::SecurityGroupIngress",
                new JsonObject
                {
                    ["GroupId"] = Ref("DatabaseSecurityGroup"),
                    ["IpProtocol"] = "tcp",
                    ["FromPort"] = 5432,
                    ["ToPort"] = 5432,
                    ["SourceSecurityGroupId"] = Ref("TaskSecurityGroup"),
                    ["Description"] = "The Trax services",
                }
            );
        }
        else
            ((JsonArray)resources["TaskSecurityGroup"]!["Properties"]!["SecurityGroupEgress"]!).Add(
                Rule(
                    "tcp",
                    5432,
                    5432,
                    cidr: "0.0.0.0/0",
                    description: "The existing Postgres database"
                )
            );

        // ---- Load balancer, TLS and the address -------------------------------------------------------------
        if (api is not null)
            AddLoadBalancer(
                resources,
                outputs,
                stack,
                env,
                exports[api],
                vpc,
                publicSubnets,
                production,
                cloudFrontPrefixList
            );

        // ---- Database ------------------------------------------------------------------------------------
        JsonObject? connection = null;
        if (env.DatabaseSecretArn is null)
        {
            AddDatabase(resources, stack, production, serviceSubnets);
            connection = Sub(
                $"Host=${{Database.Endpoint.Address}};Port=${{Database.Endpoint.Port}};Database={DatabaseName};"
                    + $"Username={DatabaseUser};SSL Mode=Require;GSS Encryption Mode=Disable"
            );
        }

        // ---- Sign-in ---------------------------------------------------------------------------------------
        if (env.Auth is { Kind: DeployAuth.Cognito })
            AddCognito(resources, outputs, stack);

        // ---- ECS -------------------------------------------------------------------------------------------
        resources["Cluster"] = Resource(
            "AWS::ECS::Cluster",
            new JsonObject { ["ClusterName"] = stack }
        );
        resources["TaskExecutionRole"] = Resource(
            "AWS::IAM::Role",
            new JsonObject
            {
                ["AssumeRolePolicyDocument"] = AssumedByTasks(),
                ["ManagedPolicyArns"] = new JsonArray(TaskExecutionPolicy),
                ["Policies"] = new JsonArray(
                    new JsonObject
                    {
                        ["PolicyName"] = "read-the-stacks-secrets",
                        ["PolicyDocument"] = new JsonObject
                        {
                            ["Version"] = "2012-10-17",
                            ["Statement"] = new JsonArray(
                                new JsonObject
                                {
                                    ["Effect"] = "Allow",
                                    ["Action"] = new JsonArray("secretsmanager:GetSecretValue"),
                                    ["Resource"] = SecretResources(file, env, stack),
                                }
                            ),
                        },
                    }
                ),
            }
        );

        var environment = new List<(string Name, JsonNode Value)>
        {
            ("Trax__Proxy__KnownNetworks", cidr.DeepClone()),
        };
        if (connection is not null)
            environment.Add(($"ConnectionStrings__{file.ConnectionStrings.Trax}", connection));
        foreach (var (name, value) in env.Settings)
            environment.Add((name, value));
        if (env.Auth is { Kind: DeployAuth.Cognito } auth)
        {
            environment.Add(
                (
                    auth.AuthorityKey,
                    Sub("https://cognito-idp.${AWS::Region}.amazonaws.com/${UserPool}")
                )
            );
            environment.Add((auth.AudienceKey, Ref("UserPoolClient")));
        }
        var secrets = new List<(string Name, JsonNode From)>();
        if (env.DatabaseSecretArn is { } byo)
            secrets.Add(($"ConnectionStrings__{file.ConnectionStrings.Trax}", byo));
        else
            secrets.Add(("PGPASSWORD", Sub("${DatabaseSecret}:password::")));
        foreach (var name in file.Secrets)
            secrets.Add((name, AppSecretName(stack, name)));

        var migrator = Migrator(file, exports);
        AddTask(
            resources,
            stack,
            MigrateContainer,
            Ref(MigrateImageParameter),
            environment,
            secrets,
            port: false,
            command: TraxMigrate.Argument
        );
        outputs["MigrateTaskDefinition"] = Output(Ref("MigrateTaskDefinition"));
        outputs["MigrateContainer"] = Output(MigrateContainer);

        var serving = environment.Append((TraxMigrate.Variable, TraxMigrate.SkipValue)).ToList();
        foreach (var service in file.Services.Keys)
        {
            var isApi = service == api;
            AddTask(
                resources,
                stack,
                service,
                Ref(ImageParameter(service)),
                serving,
                secrets,
                port: isApi,
                command: null
            );
            var id = LogicalId(service);
            var properties = new JsonObject
            {
                ["ServiceName"] = service,
                ["Cluster"] = Ref("Cluster"),
                ["LaunchType"] = "FARGATE",
                ["TaskDefinition"] = Ref($"{id}TaskDefinition"),
                ["DesiredCount"] = If("Running", file.Count(env, service), 0),
                ["DeploymentConfiguration"] = new JsonObject
                {
                    // The new copy is healthy before the old one stops, and a version that never gets healthy is
                    // rolled back.
                    ["MinimumHealthyPercent"] = 100,
                    ["MaximumPercent"] = 200,
                    ["DeploymentCircuitBreaker"] = new JsonObject
                    {
                        ["Enable"] = true,
                        ["Rollback"] = true,
                    },
                },
                ["NetworkConfiguration"] = new JsonObject
                {
                    ["AwsvpcConfiguration"] = new JsonObject
                    {
                        ["Subnets"] = serviceSubnets.DeepClone(),
                        ["SecurityGroups"] = new JsonArray(Ref("TaskSecurityGroup")),
                        ["AssignPublicIp"] = assignPublicIp,
                    },
                },
                ["EnableExecuteCommand"] = false,
                ["PropagateTags"] = "SERVICE",
            };
            var resource = Resource("AWS::ECS::Service", properties);
            if (isApi)
            {
                properties["LoadBalancers"] = new JsonArray(
                    new JsonObject
                    {
                        ["ContainerName"] = service,
                        ["ContainerPort"] = ContainerPort,
                        ["TargetGroupArn"] = Ref("TargetGroup"),
                    }
                );
                properties["HealthCheckGracePeriodSeconds"] = 120;
                resource["DependsOn"] = production
                    ? new JsonArray("HttpsListener", "HttpListener")
                    : new JsonArray("HttpListener");
            }
            resources[$"{id}Service"] = resource;
            outputs[ServiceOutput(service)] = Output(GetAtt($"{id}Service", "Name"));
        }

        outputs["ClusterName"] = Output(Ref("Cluster"));
        outputs["ServiceSubnets"] = Output(Join(",", serviceSubnets.DeepClone()));
        outputs["TaskSecurityGroup"] = Output(Ref("TaskSecurityGroup"));
        outputs["AssignPublicIp"] = Output(assignPublicIp);
        outputs["Migrator"] = Output(migrator);

        return new JsonObject
        {
            ["AWSTemplateFormatVersion"] = "2010-09-09",
            ["Description"] =
                $"Trax app {file.App}, environment {environmentName} ({env.Profile}). Written by trax deploy; "
                + "changes made outside it are reverted on the next deploy.",
            ["Parameters"] = parameters,
            ["Conditions"] = Conditions(parameters),
            ["Resources"] = resources,
            ["Outputs"] = outputs,
        };
    }

    /// <summary>The template as CloudFormation receives it: compact, so it fits the 51,200-byte inline limit.</summary>
    public static string Compact(JsonObject template) => template.ToJsonString();

    /// <summary>The template as <c>trax deploy plan</c> writes it, for reading and diffing.</summary>
    public static string Indented(JsonObject template) =>
        template.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) + "\n";

    /// <summary>Refuses what this stack cannot give the hosts.</summary>
    internal static void Check(
        DeployFile file,
        DeployEnvironment env,
        IReadOnlyDictionary<string, DeployManifest> exports
    )
    {
        ComposeTarget.CheckHosts(file, exports, name => file.Count(env, name));
        var apis = file.Services.Keys.Where(s => exports[s].Roles.Contains("api")).ToList();
        if (apis.Count > 1)
            throw new InvalidOperationException(
                $"Services {string.Join(" and ", apis)} both serve the Trax API, and a stack routes one load "
                    + "balancer to one service. Deploy one API service per app."
            );
        if (apis is [var api] && exports[api].Endpoints.Health is null)
            throw new InvalidOperationException(
                $"Service '{api}' maps no health check, which the load balancer needs to know a copy is ready. "
                    + "Add builder.Services.AddHealthChecks().AddTraxHealthCheck() and "
                    + "app.MapHealthChecks(\"/trax/health\")."
            );
        var rabbit = file
            .Services.Keys.Where(s => exports[s].Transports.Contains("rabbitmq"))
            .ToList();
        if (rabbit.Count > 0)
            throw new InvalidOperationException(
                $"Service '{rabbit[0]}' connects to RabbitMQ, which an AWS stack does not provide yet. Deploy "
                    + "with --target compose, or broadcast without RabbitMQ."
            );
        if (env.Auth is { Kind: DeployAuth.Cognito } && apis.Count == 0)
            throw new InvalidOperationException(
                "auth is cognito, and no service serves the Trax API to sign in to."
            );
    }

    // ---- Pieces ------------------------------------------------------------------------------------------

    private static JsonObject Conditions(JsonObject parameters)
    {
        var conditions = new JsonObject
        {
            ["Running"] = new JsonObject
            {
                ["Fn::Equals"] = new JsonArray(Ref(ScaleParameter), "1"),
            },
        };
        if (parameters.ContainsKey(ProtectParameter))
            conditions["Protected"] = new JsonObject
            {
                ["Fn::Equals"] = new JsonArray(Ref(ProtectParameter), "true"),
            };
        return conditions;
    }

    /// <summary>The service whose image migrates: the one serving the API, else the first.</summary>
    public static string Migrator(
        DeployFile file,
        IReadOnlyDictionary<string, DeployManifest> exports
    ) =>
        file.Services.Keys.FirstOrDefault(s => exports[s].Roles.Contains("api"))
        ?? file.Services.Keys.First();

    private static void AddVpc(JsonObject resources, string stack, bool production)
    {
        resources["Vpc"] = Resource(
            "AWS::EC2::VPC",
            new JsonObject
            {
                ["CidrBlock"] = VpcCidr,
                ["EnableDnsSupport"] = true,
                ["EnableDnsHostnames"] = true,
                ["Tags"] = NameTag(stack),
            }
        );
        resources["InternetGateway"] = Resource(
            "AWS::EC2::InternetGateway",
            new JsonObject { ["Tags"] = NameTag(stack) }
        );
        resources["InternetGatewayAttachment"] = Resource(
            "AWS::EC2::VPCGatewayAttachment",
            new JsonObject
            {
                ["VpcId"] = Ref("Vpc"),
                ["InternetGatewayId"] = Ref("InternetGateway"),
            }
        );
        resources["PublicRouteTable"] = Resource(
            "AWS::EC2::RouteTable",
            new JsonObject { ["VpcId"] = Ref("Vpc"), ["Tags"] = NameTag($"{stack}-public") }
        );
        var publicRoute = Resource(
            "AWS::EC2::Route",
            new JsonObject
            {
                ["RouteTableId"] = Ref("PublicRouteTable"),
                ["DestinationCidrBlock"] = "0.0.0.0/0",
                ["GatewayId"] = Ref("InternetGateway"),
            }
        );
        publicRoute["DependsOn"] = "InternetGatewayAttachment";
        resources["PublicRoute"] = publicRoute;

        var zones = new[] { ("A", 0), ("B", 1) };
        foreach (var (letter, index) in zones)
        {
            resources[$"PublicSubnet{letter}"] = Subnet(
                stack,
                $"10.0.{index * 16}.0/20",
                index,
                "public"
            );
            resources[$"PublicSubnet{letter}RouteTable"] = Resource(
                "AWS::EC2::SubnetRouteTableAssociation",
                new JsonObject
                {
                    ["SubnetId"] = Ref($"PublicSubnet{letter}"),
                    ["RouteTableId"] = Ref("PublicRouteTable"),
                }
            );
        }
        if (!production)
            return;

        // The services and the database live in private subnets and go out through one NAT gateway.
        resources["NatAddress"] = Resource(
            "AWS::EC2::EIP",
            new JsonObject { ["Domain"] = "vpc", ["Tags"] = NameTag(stack) }
        );
        resources["NatGateway"] = Resource(
            "AWS::EC2::NatGateway",
            new JsonObject
            {
                ["AllocationId"] = GetAtt("NatAddress", "AllocationId"),
                ["SubnetId"] = Ref("PublicSubnetA"),
                ["Tags"] = NameTag(stack),
            }
        );
        resources["PrivateRouteTable"] = Resource(
            "AWS::EC2::RouteTable",
            new JsonObject { ["VpcId"] = Ref("Vpc"), ["Tags"] = NameTag($"{stack}-private") }
        );
        resources["PrivateRoute"] = Resource(
            "AWS::EC2::Route",
            new JsonObject
            {
                ["RouteTableId"] = Ref("PrivateRouteTable"),
                ["DestinationCidrBlock"] = "0.0.0.0/0",
                ["NatGatewayId"] = Ref("NatGateway"),
            }
        );
        foreach (var (letter, index) in zones)
        {
            resources[$"PrivateSubnet{letter}"] = Subnet(
                stack,
                $"10.0.{128 + index * 16}.0/20",
                index,
                "private"
            );
            resources[$"PrivateSubnet{letter}RouteTable"] = Resource(
                "AWS::EC2::SubnetRouteTableAssociation",
                new JsonObject
                {
                    ["SubnetId"] = Ref($"PrivateSubnet{letter}"),
                    ["RouteTableId"] = Ref("PrivateRouteTable"),
                }
            );
        }
    }

    private static JsonObject Subnet(string stack, string cidr, int zone, string kind) =>
        Resource(
            "AWS::EC2::Subnet",
            new JsonObject
            {
                ["VpcId"] = Ref("Vpc"),
                ["CidrBlock"] = cidr,
                ["AvailabilityZone"] = new JsonObject
                {
                    ["Fn::Select"] = new JsonArray(zone, new JsonObject { ["Fn::GetAZs"] = "" }),
                },
                ["MapPublicIpOnLaunch"] = false,
                ["Tags"] = NameTag($"{stack}-{kind}-{(char)('a' + zone)}"),
            }
        );

    private static void AddLoadBalancer(
        JsonObject resources,
        JsonObject outputs,
        string stack,
        DeployEnvironment env,
        DeployManifest api,
        JsonNode vpc,
        JsonArray publicSubnets,
        bool production,
        string? cloudFrontPrefixList
    )
    {
        // Production takes HTTPS from anywhere and redirects HTTP; try takes HTTP from CloudFront alone.
        JsonArray ingress = production
            ?
            [
                Rule("tcp", 443, 443, cidr: "0.0.0.0/0", description: "HTTPS"),
                Rule("tcp", 443, 443, cidrV6: "::/0", description: "HTTPS"),
                Rule("tcp", 80, 80, cidr: "0.0.0.0/0", description: "Redirected to HTTPS"),
                Rule("tcp", 80, 80, cidrV6: "::/0", description: "Redirected to HTTPS"),
            ]
            : [Rule("tcp", 80, 80, prefixList: cloudFrontPrefixList, description: "CloudFront")];
        var albGroup = SecurityGroup(stack, vpc, "The load balancer", []);
        ((JsonObject)albGroup["Properties"]!)["SecurityGroupIngress"] = ingress;
        ((JsonObject)albGroup["Properties"]!)["SecurityGroupEgress"] = new JsonArray(
            Rule(
                "-1",
                null,
                null,
                cidr: "127.0.0.1/32",
                description: "Replaced by the rule to the services"
            )
        );
        resources["LoadBalancerSecurityGroup"] = albGroup;
        resources["LoadBalancerToTasks"] = Resource(
            "AWS::EC2::SecurityGroupEgress",
            new JsonObject
            {
                ["GroupId"] = Ref("LoadBalancerSecurityGroup"),
                ["IpProtocol"] = "tcp",
                ["FromPort"] = ContainerPort,
                ["ToPort"] = ContainerPort,
                ["DestinationSecurityGroupId"] = Ref("TaskSecurityGroup"),
                ["Description"] = "The API service",
            }
        );
        resources["TasksFromLoadBalancer"] = Resource(
            "AWS::EC2::SecurityGroupIngress",
            new JsonObject
            {
                ["GroupId"] = Ref("TaskSecurityGroup"),
                ["IpProtocol"] = "tcp",
                ["FromPort"] = ContainerPort,
                ["ToPort"] = ContainerPort,
                ["SourceSecurityGroupId"] = Ref("LoadBalancerSecurityGroup"),
                ["Description"] = "The load balancer",
            }
        );

        var balancer = Resource(
            "AWS::ElasticLoadBalancingV2::LoadBalancer",
            new JsonObject
            {
                ["Scheme"] = "internet-facing",
                ["Type"] = "application",
                ["Subnets"] = publicSubnets.DeepClone(),
                ["SecurityGroups"] = new JsonArray(Ref("LoadBalancerSecurityGroup")),
                ["LoadBalancerAttributes"] = new JsonArray(
                    Attribute("routing.http.drop_invalid_header_fields.enabled", "true"),
                    // Subscriptions hold a socket open; the default 60 seconds would cut an idle one.
                    Attribute("idle_timeout.timeout_seconds", "300")
                ),
                ["Tags"] = NameTag(stack),
            }
        );
        if (env.Network is null)
            balancer["DependsOn"] = "InternetGatewayAttachment";
        resources["LoadBalancer"] = balancer;
        resources["TargetGroup"] = Resource(
            "AWS::ElasticLoadBalancingV2::TargetGroup",
            new JsonObject
            {
                ["TargetType"] = "ip",
                ["Protocol"] = "HTTP",
                ["Port"] = ContainerPort,
                ["VpcId"] = vpc.DeepClone(),
                ["HealthCheckPath"] = api.Endpoints.Health,
                ["Matcher"] = new JsonObject { ["HttpCode"] = "200" },
                ["HealthCheckIntervalSeconds"] = 15,
                ["HealthyThresholdCount"] = 2,
                ["TargetGroupAttributes"] = new JsonArray(
                    Attribute("deregistration_delay.timeout_seconds", "30")
                ),
                ["Tags"] = NameTag(stack),
            }
        );

        var forward = new JsonArray(
            new JsonObject { ["Type"] = "forward", ["TargetGroupArn"] = Ref("TargetGroup") }
        );
        if (production)
        {
            var certificate = new JsonObject
            {
                ["DomainName"] = env.Domain,
                ["ValidationMethod"] = "DNS",
                ["Tags"] = NameTag(stack),
            };
            if (env.HostedZoneId is not null)
                certificate["DomainValidationOptions"] = new JsonArray(
                    new JsonObject
                    {
                        ["DomainName"] = env.Domain,
                        ["HostedZoneId"] = env.HostedZoneId,
                    }
                );
            resources["Certificate"] = Resource(
                "AWS::CertificateManager::Certificate",
                certificate
            );
            resources["HttpsListener"] = Resource(
                "AWS::ElasticLoadBalancingV2::Listener",
                new JsonObject
                {
                    ["LoadBalancerArn"] = Ref("LoadBalancer"),
                    ["Port"] = 443,
                    ["Protocol"] = "HTTPS",
                    ["SslPolicy"] = "ELBSecurityPolicy-TLS13-1-2-2021-06",
                    ["Certificates"] = new JsonArray(
                        new JsonObject { ["CertificateArn"] = Ref("Certificate") }
                    ),
                    ["DefaultActions"] = forward,
                }
            );
            resources["HttpListener"] = Resource(
                "AWS::ElasticLoadBalancingV2::Listener",
                new JsonObject
                {
                    ["LoadBalancerArn"] = Ref("LoadBalancer"),
                    ["Port"] = 80,
                    ["Protocol"] = "HTTP",
                    ["DefaultActions"] = new JsonArray(
                        new JsonObject
                        {
                            ["Type"] = "redirect",
                            ["RedirectConfig"] = new JsonObject
                            {
                                ["Protocol"] = "HTTPS",
                                ["Port"] = "443",
                                ["StatusCode"] = "HTTP_301",
                            },
                        }
                    ),
                }
            );
            if (env.HostedZoneId is not null)
                resources["DomainRecord"] = Resource(
                    "AWS::Route53::RecordSet",
                    new JsonObject
                    {
                        ["HostedZoneId"] = env.HostedZoneId,
                        ["Name"] = env.Domain,
                        ["Type"] = "A",
                        ["AliasTarget"] = new JsonObject
                        {
                            ["DNSName"] = GetAtt("LoadBalancer", "DNSName"),
                            ["HostedZoneId"] = GetAtt("LoadBalancer", "CanonicalHostedZoneID"),
                        },
                    }
                );
            outputs["Url"] = Output($"https://{env.Domain}");
        }
        else
        {
            resources["HttpListener"] = Resource(
                "AWS::ElasticLoadBalancingV2::Listener",
                new JsonObject
                {
                    ["LoadBalancerArn"] = Ref("LoadBalancer"),
                    ["Port"] = 80,
                    ["Protocol"] = "HTTP",
                    ["DefaultActions"] = forward,
                }
            );
            resources["Distribution"] = Resource(
                "AWS::CloudFront::Distribution",
                new JsonObject
                {
                    ["DistributionConfig"] = new JsonObject
                    {
                        ["Enabled"] = true,
                        ["Comment"] = stack,
                        ["HttpVersion"] = "http2and3",
                        ["PriceClass"] = "PriceClass_100",
                        ["Origins"] = new JsonArray(
                            new JsonObject
                            {
                                ["Id"] = "load-balancer",
                                ["DomainName"] = GetAtt("LoadBalancer", "DNSName"),
                                ["CustomOriginConfig"] = new JsonObject
                                {
                                    ["OriginProtocolPolicy"] = "http-only",
                                    ["HTTPPort"] = 80,
                                    ["OriginReadTimeout"] = 60,
                                },
                            }
                        ),
                        ["DefaultCacheBehavior"] = new JsonObject
                        {
                            ["TargetOriginId"] = "load-balancer",
                            ["ViewerProtocolPolicy"] = "redirect-to-https",
                            ["AllowedMethods"] = new JsonArray(
                                "GET",
                                "HEAD",
                                "OPTIONS",
                                "PUT",
                                "PATCH",
                                "POST",
                                "DELETE"
                            ),
                            ["CachePolicyId"] = CachingDisabledPolicy,
                            ["OriginRequestPolicyId"] = AllViewerOriginRequestPolicy,
                        },
                    },
                }
            );
            outputs["Url"] = Output(Sub("https://${Distribution.DomainName}"));
        }
        outputs["LoadBalancerDnsName"] = Output(GetAtt("LoadBalancer", "DNSName"));
        outputs["GraphQLPath"] = Output(api.Endpoints.GraphQL ?? "");
        outputs["HealthPath"] = Output(api.Endpoints.Health ?? "");
    }

    private static void AddDatabase(
        JsonObject resources,
        string stack,
        bool production,
        JsonArray subnets
    )
    {
        // Generated once by Secrets Manager and never rotated: a running task reads it at start, and a rotated
        // password would stop every task until it restarted.
        resources["DatabaseSecret"] = Resource(
            "AWS::SecretsManager::Secret",
            new JsonObject
            {
                ["Name"] = $"{stack}/database",
                ["Description"] = "The password the Trax services sign in to Postgres with.",
                ["GenerateSecretString"] = new JsonObject
                {
                    ["SecretStringTemplate"] = $"{{\"username\":\"{DatabaseUser}\"}}",
                    ["GenerateStringKey"] = "password",
                    ["PasswordLength"] = 40,
                    ["ExcludePunctuation"] = true,
                },
            }
        );
        resources["DatabaseSubnetGroup"] = Resource(
            "AWS::RDS::DBSubnetGroup",
            new JsonObject
            {
                ["DBSubnetGroupDescription"] = $"{stack} database",
                ["SubnetIds"] = subnets.DeepClone(),
            }
        );
        var database = Resource(
            "AWS::RDS::DBInstance",
            new JsonObject
            {
                ["Engine"] = "postgres",
                ["EngineVersion"] = "17",
                ["DBInstanceClass"] = production ? "db.t4g.small" : "db.t4g.micro",
                ["AllocatedStorage"] = "20",
                ["StorageType"] = "gp3",
                ["StorageEncrypted"] = true,
                ["MultiAZ"] = production,
                ["PubliclyAccessible"] = false,
                ["DBName"] = DatabaseName,
                ["MasterUsername"] = Sub(
                    "{{resolve:secretsmanager:${DatabaseSecret}:SecretString:username}}"
                ),
                ["MasterUserPassword"] = Sub(
                    "{{resolve:secretsmanager:${DatabaseSecret}:SecretString:password}}"
                ),
                ["DBSubnetGroupName"] = Ref("DatabaseSubnetGroup"),
                ["VPCSecurityGroups"] = new JsonArray(Ref("DatabaseSecurityGroup")),
                ["BackupRetentionPeriod"] = production ? 7 : 1,
                ["DeletionProtection"] = production
                    ? If("Protected", true, false)
                    : (JsonNode)false,
                ["AutoMinorVersionUpgrade"] = true,
                ["CopyTagsToSnapshot"] = true,
                ["Tags"] = NameTag(stack),
            }
        );
        // Production keeps a final snapshot when the stack is deleted; try deletes its database with it.
        database["DeletionPolicy"] = production ? "Snapshot" : "Delete";
        database["UpdateReplacePolicy"] = production ? "Snapshot" : "Delete";
        resources["Database"] = database;
    }

    private static void AddCognito(JsonObject resources, JsonObject outputs, string stack)
    {
        resources["UserPool"] = Resource(
            "AWS::Cognito::UserPool",
            new JsonObject
            {
                ["UserPoolName"] = stack,
                ["UsernameAttributes"] = new JsonArray("email"),
                ["AutoVerifiedAttributes"] = new JsonArray("email"),
                // Users are invited by an operator, never self-registered.
                ["AdminCreateUserConfig"] = new JsonObject { ["AllowAdminCreateUserOnly"] = true },
                ["MfaConfiguration"] = "OPTIONAL",
                ["EnabledMfas"] = new JsonArray("SOFTWARE_TOKEN_MFA"),
                ["Policies"] = new JsonObject
                {
                    ["PasswordPolicy"] = new JsonObject
                    {
                        ["MinimumLength"] = 12,
                        ["RequireLowercase"] = true,
                        ["RequireUppercase"] = true,
                        ["RequireNumbers"] = true,
                        ["RequireSymbols"] = false,
                    },
                },
            }
        );
        resources["UserPoolClient"] = Resource(
            "AWS::Cognito::UserPoolClient",
            new JsonObject
            {
                ["UserPoolId"] = Ref("UserPool"),
                ["ClientName"] = $"{stack}-api",
                ["GenerateSecret"] = false,
                ["ExplicitAuthFlows"] = new JsonArray(
                    "ALLOW_USER_SRP_AUTH",
                    "ALLOW_REFRESH_TOKEN_AUTH"
                ),
                ["PreventUserExistenceErrors"] = "ENABLED",
                ["EnableTokenRevocation"] = true,
            }
        );
        resources["OperatorGroup"] = Resource(
            "AWS::Cognito::UserPoolGroup",
            new JsonObject
            {
                ["UserPoolId"] = Ref("UserPool"),
                ["GroupName"] = "Operator",
                ["Description"] = "May use the operations namespace and the console.",
            }
        );
        outputs["UserPoolId"] = Output(Ref("UserPool"));
        outputs["UserPoolClientId"] = Output(Ref("UserPoolClient"));
    }

    private static void AddTask(
        JsonObject resources,
        string stack,
        string name,
        JsonNode image,
        IReadOnlyList<(string Name, JsonNode Value)> environment,
        IReadOnlyList<(string Name, JsonNode From)> secrets,
        bool port,
        string? command
    )
    {
        var id = LogicalId(name);
        resources[$"{id}Logs"] = Resource(
            "AWS::Logs::LogGroup",
            new JsonObject { ["LogGroupName"] = LogGroup(stack, name), ["RetentionInDays"] = 30 }
        );
        resources[$"{id}TaskRole"] = Resource(
            "AWS::IAM::Role",
            new JsonObject
            {
                ["AssumeRolePolicyDocument"] = AssumedByTasks(),
                ["Description"] = $"The {name} task's own permissions: none until it needs one.",
            }
        );
        var container = new JsonObject
        {
            ["Name"] = name,
            ["Image"] = image,
            ["Essential"] = true,
            ["Environment"] = new JsonArray([
                .. environment.Select(e =>
                    (JsonNode)new JsonObject { ["Name"] = e.Name, ["Value"] = e.Value.DeepClone() }
                ),
            ]),
            ["Secrets"] = new JsonArray([
                .. secrets.Select(s =>
                    (JsonNode)
                        new JsonObject { ["Name"] = s.Name, ["ValueFrom"] = s.From.DeepClone() }
                ),
            ]),
            ["LogConfiguration"] = new JsonObject
            {
                ["LogDriver"] = "awslogs",
                ["Options"] = new JsonObject
                {
                    ["awslogs-group"] = Ref($"{id}Logs"),
                    ["awslogs-region"] = Ref("AWS::Region"),
                    ["awslogs-stream-prefix"] = name,
                },
            },
        };
        if (port)
            container["PortMappings"] = new JsonArray(
                new JsonObject { ["ContainerPort"] = ContainerPort, ["Protocol"] = "tcp" }
            );
        if (command is not null)
            container["Command"] = new JsonArray(command);
        resources[$"{id}TaskDefinition"] = Resource(
            "AWS::ECS::TaskDefinition",
            new JsonObject
            {
                ["Family"] = $"{stack}-{name}",
                ["Cpu"] = "512",
                ["Memory"] = "1024",
                ["NetworkMode"] = "awsvpc",
                ["RequiresCompatibilities"] = new JsonArray("FARGATE"),
                ["RuntimePlatform"] = new JsonObject
                {
                    ["CpuArchitecture"] = "X86_64",
                    ["OperatingSystemFamily"] = "LINUX",
                },
                ["ExecutionRoleArn"] = GetAtt("TaskExecutionRole", "Arn"),
                ["TaskRoleArn"] = GetAtt($"{id}TaskRole", "Arn"),
                ["ContainerDefinitions"] = new JsonArray(container),
            }
        );
    }

    private static JsonArray SecretResources(DeployFile file, DeployEnvironment env, string stack)
    {
        var resources = new JsonArray();
        if (env.DatabaseSecretArn is { } byo)
            resources.Add(byo);
        else
            resources.Add(Ref("DatabaseSecret"));
        if (file.Secrets.Count > 0)
            resources.Add(
                Sub(
                    $"arn:${{AWS::Partition}}:secretsmanager:${{AWS::Region}}:${{AWS::AccountId}}:secret:{stack}/app/*"
                )
            );
        return resources;
    }

    /// <summary>The Secrets Manager name an app secret is stored under: <c>&lt;stack&gt;/app/&lt;NAME&gt;</c>.</summary>
    public static string AppSecretName(string stack, string name) => $"{stack}/app/{name}";

    public static string LogGroup(string stack, string service) => $"/trax/{stack}/{service}";

    /// <summary><c>order-worker</c> becomes <c>OrderWorker</c>.</summary>
    public static string LogicalId(string name) =>
        string.Concat(
            name.Split('-', StringSplitOptions.RemoveEmptyEntries)
                .Select(p => char.ToUpperInvariant(p[0]) + p[1..])
        );

    /// <summary>The database the stack creates inside its instance.</summary>
    public const string DatabaseName = "trax";

    private static JsonObject SecurityGroup(
        string stack,
        JsonNode vpc,
        string description,
        JsonArray egress
    ) =>
        Resource(
            "AWS::EC2::SecurityGroup",
            new JsonObject
            {
                ["GroupDescription"] = $"{stack}: {description}",
                ["VpcId"] = vpc.DeepClone(),
                ["SecurityGroupEgress"] = egress,
                ["Tags"] = NameTag(stack),
            }
        );

    private static JsonObject Rule(
        string protocol,
        int? from,
        int? to,
        string? cidr = null,
        string? cidrV6 = null,
        string? prefixList = null,
        string? description = null
    )
    {
        var rule = new JsonObject { ["IpProtocol"] = protocol };
        if (from is not null)
            rule["FromPort"] = from;
        if (to is not null)
            rule["ToPort"] = to;
        if (cidr is not null)
            rule["CidrIp"] = cidr;
        if (cidrV6 is not null)
            rule["CidrIpv6"] = cidrV6;
        if (prefixList is not null)
            rule["SourcePrefixListId"] = prefixList;
        if (description is not null)
            rule["Description"] = description;
        return rule;
    }

    private static JsonObject AssumedByTasks() =>
        new()
        {
            ["Version"] = "2012-10-17",
            ["Statement"] = new JsonArray(
                new JsonObject
                {
                    ["Effect"] = "Allow",
                    ["Principal"] = new JsonObject { ["Service"] = "ecs-tasks.amazonaws.com" },
                    ["Action"] = "sts:AssumeRole",
                }
            ),
        };

    private static JsonObject Attribute(string key, string value) =>
        new() { ["Key"] = key, ["Value"] = value };

    private static JsonArray NameTag(string name) =>
        [new JsonObject { ["Key"] = "Name", ["Value"] = name }];

    private static JsonObject Resource(string type, JsonObject properties) =>
        new() { ["Type"] = type, ["Properties"] = properties };

    private static JsonObject Output(JsonNode value) => new() { ["Value"] = value };

    private static JsonObject Ref(string name) => new() { ["Ref"] = name };

    private static JsonObject GetAtt(string resource, string attribute) =>
        new() { ["Fn::GetAtt"] = new JsonArray(resource, attribute) };

    private static JsonObject Sub(string text) => new() { ["Fn::Sub"] = text };

    private static JsonObject Join(string separator, JsonNode values) =>
        new() { ["Fn::Join"] = new JsonArray(separator, values) };

    private static JsonObject If(string condition, JsonNode whenTrue, JsonNode whenFalse) =>
        new() { ["Fn::If"] = new JsonArray(condition, whenTrue, whenFalse) };
}
